  +'<label>Тариф, ₽ за кВт·ч</label><input id="c-t" type="number" step="0.1" inputmode="decimal" placeholder="8.5">'
  +'<button class="btn" onclick="doCalc()">Рассчитать</button><div id="c-out"></div>';
