function doCalc(){var kw=parseFloat(el('c-kw').value),pw=parseFloat(el('c-pw').value),a=parseFloat(el('c-a').value),b=parseFloat(el('c-b').value),t=parseFloat(el('c-t').value);
 if(!kw||!pw||isNaN(a)||isNaN(b)||a<0||b>100||a>=b){toast('Заполните поля корректно');return;}
 var need=kw*(b-a)/100*1.08;
 var hours=need/pw;var cost=need*(t||0);
 try{localStorage.setItem('zs_tariff',String(t||''));}catch(e){}
 el('c-out').innerHTML='<div class="res">Энергия: <b>'+need.toFixed(1)+' кВт·ч</b> (с потерями ~8%)<br>Время: <b>'+fmt(hours*60)+' мин</b> ('+hours.toFixed(1)+' ч)<br>Стоимость: <b>'+(t?fmt(cost)+' ₽':'укажите тариф')+'</b></div><p class="sub">Тариф сохранён для следующего раза.</p>';}
function renderLog(){var j=loadJ();var now=Date.now();
 function daysAgo(e){return (now-new Date(e.d).getTime())/864e5;}
 var w=j.filter(function(e){return daysAgo(e)<=7;}).length;
 var m30=j.filter(function(e){return daysAgo(e)<=30;});
 var km30=m30.reduce(function(s,e){return s+(+e.km||0);},0);
 var q90=j.filter(function(e){return daysAgo(e)<=90;});
 var kj=q90.reduce(function(s,e){return s+(+e.k||0);},0);
 var km90=q90.reduce(function(s,e){return s+(+e.km||0);},0);
 var rj=q90.reduce(function(s,e){return s+(+e.r||0);},0);
 var os='';j.slice().reverse().forEach(function(e){os+='<div class="item"><span>'+esc(String(e.d).slice(0,10))+' · '+(+e.km||0)+' км · '+(+e.k||0)+' кВт·ч'+(+e.r?' · '+fmt(+e.r)+' ₽':'')+'</span><button class="cnt" onclick="delJ(\''+e.id+'\')" style="border:none;background:none;cursor:pointer;min-width:40px;min-height:44px;font-size:16px">✕</button></div>';});
 if(!j.length)os='<p class="sub">Пока пусто. Записывайте зарядки — через 90 дней увидите реальную статистику владения.</p>';
 el('app-log').innerHTML='<div class="h">📒 Журнал зарядок</div>'
  +'<div class="card"><div class="kv"><b>За 7 дней</b><span>'+w+' зарядок</span></div>'
  +'<div class="kv"><b>За 30 дней</b><span>'+m30.length+' зарядок · '+fmt(km30)+' км</span></div>'
  +'<div class="kv"><b>За 90 дней</b><span>'+fmt(kj)+' кВт·ч · '+(rj?fmt(rj)+' ₽':'—')+'</span></div>'
  +(km90&&kj?('<div class="kv"><b>Средний расход</b><span>'+(kj/km90*100).toFixed(1)+' кВт·ч / 100 км</span></div>'):'')+'</div>'
  +'<div class="card"><label>Дата</label><input id="j-d" type="date"><div class="row2"><div><label>Пробег за день, км</label><input id="j-km" type="number" inputmode="numeric"></div><div><label>Заряжено, кВт·ч</label><input id="j-k" type="number" step="0.1" inputmode="decimal"></div></div>'
  +'<label>Оплатили, ₽ (необязательно)</label><input id="j-r" type="number" inputmode="numeric">'
  +'<button class="btn" onclick="addJ()">Добавить запись</button></div>'
  +'<div class="card list" id="j-list">'+os+'</div>';}
function addJ(){var d=el('j-d').value||new Date().toISOString().slice(0,10);var km=+el('j-km').value||0,k=+el('j-k').value||0,r=+el('j-r').value||0;
