 var j=loadJ();j.push({id:Math.random().toString(36).slice(2,8),d:d,km:km,k:k,r:r});saveJ(j);renderLog();toast('Запись добавлена');}
function delJ(id){var j=loadJ().filter(function(e){return e.id!==id;});saveJ(j);renderLog();}
